def countCircleSeatPlans(n, k):
    MOD = 10 ** 9 + 7
    if k == 0:
        return 1
    m = n - k
    prod = 1
    for i in range(k):
        prod = prod * ((m - i) % MOD) % MOD
    fact_k = 1
    for i in range(1, k + 1):
        fact_k = fact_k * i % MOD
    comb = prod * pow(fact_k, MOD - 2, MOD) % MOD
    return n % MOD * comb % MOD * pow(m % MOD, MOD - 2, MOD) % MOD
